import re, sys, os, json, urllib.request, urllib.parse, tempfile
import openpyxl
from playwright.sync_api import sync_playwright, expect

BASE = 'http://127.0.0.1:54321'
CHROME = os.environ.get('CHROME_PATH', '/opt/pw-browsers/chromium-1194/chrome-linux/chrome')
INIT = "window.WAAD_CONFIG={url:'%s',key:'test-publishable-key'}" % BASE
PW = 'Passw0rd!x'
results = []
def ok(c, name):
    results.append((bool(c), name)); print(('PASS ' if c else 'FAIL ') + name, flush=True)
def sql(q):
    req = urllib.request.Request(BASE + '/mock/sql', data=json.dumps({'q': q}).encode(), headers={'Content-Type': 'application/json'})
    return json.loads(urllib.request.urlopen(req).read())['r']

def sqlx(q):
    req = urllib.request.Request(BASE + '/mock/exec', data=json.dumps({'q': q}).encode(), headers={'Content-Type': 'application/json'})
    return json.loads(urllib.request.urlopen(req).read())['r']

def new_page(b, mobile=False):
    ctx = b.new_context(viewport={'width': 390, 'height': 844} if mobile else {'width': 1280, 'height': 900}, locale='ar-SA')
    ctx.add_init_script(INIT)
    ctx.route(re.compile(r'https://fonts\.(googleapis|gstatic)\.com/.*'), lambda r: r.abort())
    p = ctx.new_page(); p.errors = []
    p.on('pageerror', lambda e: p.errors.append(str(e)))
    p.on('console', lambda m: m.type == 'error' and 'net::ERR_FAILED' not in m.text and 'Failed to load resource' not in m.text and p.errors.append(m.text))
    p.goto(BASE + '/waad-app.html'); return p

def signup(p, email):
    p.click('[data-go=up]')
    p.fill('input[name=email]', email); p.fill('input[name=password]', PW); p.fill('input[name=password2]', PW); p.check('input[name=agree]')
    p.click('#ab')

def modal_ok(p):
    p.click('#mok')
    try: p.wait_for_selector('#dlg', state='hidden', timeout=8000)
    except Exception: raise AssertionError('modal stayed open: ' + p.inner_text('#merr') + ' | ' + '; '.join(p.errors))
def um(p, sel):
    if p.locator('#umenu').is_hidden(): p.click('#um')
    p.click(sel)
def go(p, h): p.evaluate(f"location.hash='{h}'"); p.wait_for_timeout(350)

