    # ---------- two-step verification ----------
    import hmac, hashlib, struct, base64 as b64, time as tm
    def totp(sec):
        k = b64.b32decode(sec + '=' * (-len(sec) % 8)); h = hmac.new(k, struct.pack('>Q', int(tm.time() // 30)), hashlib.sha1).digest(); x = h[-1] & 15
        return '%06d' % ((struct.unpack('>I', h[x:x + 4])[0] & 0x7fffffff) % 1000000)
